  account_id UUID REFERENCES wacrm.accounts(id) ON DELETE CASCADE NOT NULL,
  phone_normalized TEXT
  GENERATED ALWAYS AS (regexp_replace(phone, '\D', '', 'g')) STORED,
  wa_user_id TEXT,
