  interactive_payload JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE wacrm.consent_events (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  account_id UUID NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  contact_id UUID NOT NULL REFERENCES wacrm.contacts(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL CHECK (event_type IN ('opt_out', 'opt_in', 'send_skipped')),
  source TEXT NOT NULL DEFAULT 'inbound_keyword' CHECK (source IN ( 'inbound_keyword', 'broadcast', 'automation', 'adapter', 'manual', 'system' )),
  keyword TEXT,
  channel TEXT NOT NULL DEFAULT 'whatsapp',
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE wacrm.astra_connect_handoff_audit (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  account_id UUID NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  conversation_id UUID NOT NULL REFERENCES wacrm.conversations(id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('takeover', 'handback')),
  by_actor TEXT,
  source TEXT NOT NULL DEFAULT 'api' CHECK (source IN ('api', 'inbox', 'adapter')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  reason TEXT
);

CREATE TABLE wacrm.astra_usage_daily (
  account_id UUID NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  day DATE NOT NULL,
  inbound_messages BIGINT NOT NULL DEFAULT 0,
  outbound_messages BIGINT NOT NULL DEFAULT 0,
  template_sends BIGINT NOT NULL DEFAULT 0,
  conversations BIGINT NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (account_id, day)
);

CREATE TABLE wacrm.integration_connections (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id            uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  provider              text NOT NULL,
  status                text NOT NULL DEFAULT 'disconnected' CHECK (status IN ('disconnected', 'connected', 'error')),
  credentials_encrypted text,
  config                jsonb NOT NULL DEFAULT '{}'::jsonb,
  display_name          text,
  last_tested_at        timestamptz,
  last_error            text,
  connected_at          timestamptz,
  connected_by          uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_at            timestamptz NOT NULL DEFAULT now(),
  created_at            timestamptz NOT NULL DEFAULT now(),
  UNIQUE (account_id, provider)
);

CREATE TABLE wacrm.integration_event_log (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id  uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  provider    text NOT NULL,
  event_type  text NOT NULL,
  status      text NOT NULL DEFAULT 'info' CHECK (status IN ('info', 'success', 'error', 'skipped')),
  message     text,
  payload     jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.webhook_delivery_queue (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id      uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  endpoint_id     uuid NOT NULL REFERENCES wacrm.webhook_endpoints(id) ON DELETE CASCADE,
  event           text NOT NULL,
  payload         jsonb NOT NULL,
  attempt         integer NOT NULL DEFAULT 0,
  max_attempts    integer NOT NULL DEFAULT 8,
  next_attempt_at timestamptz NOT NULL DEFAULT now(),
  last_error      text,
  status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivered', 'dead')),
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.ecommerce_orders (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id   uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  provider     text NOT NULL CHECK (provider IN ('shopify', 'woocommerce')),
  external_id  text NOT NULL,
  event_type   text NOT NULL,
  status       text,
  phone_e164   text,
  email        text,
  currency     text,
  total        text,
  payload      jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (account_id, provider, external_id, event_type)
);

CREATE TABLE wacrm.ecommerce_notify_queue (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id      uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  provider        text NOT NULL,
  order_id        uuid REFERENCES wacrm.ecommerce_orders(id) ON DELETE SET NULL,
  contact_id      uuid REFERENCES wacrm.contacts(id) ON DELETE SET NULL,
  phone_e164      text,
  template_name   text,
  template_lang   text NOT NULL DEFAULT 'en',
  delay_seconds   integer NOT NULL DEFAULT 0,
  run_at          timestamptz NOT NULL DEFAULT now(),
  status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'skipped', 'failed')),
  last_error      text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.product_catalog_items (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id   uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  provider     text NOT NULL CHECK (provider IN ('shopify', 'woocommerce')),
  external_id  text NOT NULL,
  title        text NOT NULL,
  sku          text,
  price        text,
  currency     text,
  raw          jsonb NOT NULL DEFAULT '{}'::jsonb,
  synced_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (account_id, provider, external_id)
);

CREATE TABLE wacrm.payment_links (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id       uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  conversation_id  uuid REFERENCES wacrm.conversations(id) ON DELETE SET NULL,
  contact_id       uuid REFERENCES wacrm.contacts(id) ON DELETE SET NULL,
  provider         text NOT NULL CHECK (provider IN ('razorpay', 'stripe')),
  external_id      text,
  url              text NOT NULL,
  amount_cents     integer NOT NULL,
  currency         text NOT NULL DEFAULT 'INR',
  description      text,
  status           text NOT NULL DEFAULT 'created' CHECK (status IN ('created', 'paid', 'failed', 'expired', 'cancelled')),
  created_by       uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  raw              jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at       timestamptz NOT NULL DEFAULT now(),
  updated_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.sheets_sync_runs (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id      uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  direction       text NOT NULL CHECK (direction IN ('import', 'export')),
  spreadsheet_id  text NOT NULL,
  sheet_name      text,
  status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'success', 'error')),
  rows_ok         integer NOT NULL DEFAULT 0,
  rows_error      integer NOT NULL DEFAULT 0,
  message         text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  finished_at     timestamptz
);

CREATE TABLE wacrm.crm_push_log (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id      uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  provider        text NOT NULL CHECK (provider IN ('hubspot', 'zoho', 'astra_crm')),
  entity_type     text NOT NULL CHECK (entity_type IN ('contact', 'note', 'conversation_summary')),
  contact_id      uuid REFERENCES wacrm.contacts(id) ON DELETE SET NULL,
  external_id     text,
  status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'success', 'error', 'deduped')),
  attempt         integer NOT NULL DEFAULT 0,
  last_error      text,
  payload         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.ad_attributions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  contact_id uuid REFERENCES wacrm.contacts(id) ON DELETE SET NULL,
  conversation_id uuid REFERENCES wacrm.conversations(id) ON DELETE SET NULL,
  source_id text,
  ctwa_clid text,
  headline text,
  ad_id text,
  body text,
  source_type text,
  source_url text,
  converted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.intents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id uuid NOT NULL REFERENCES wacrm.accounts(id) ON DELETE CASCADE,
  name text NOT NULL,
  display_name text NOT NULL,
  description text,
  enabled boolean NOT NULL DEFAULT true,
  trigger_flow_id uuid REFERENCES wacrm.flows(id) ON DELETE SET NULL,
  trigger_automation_id uuid REFERENCES wacrm.automations(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (account_id, name)
);

CREATE TABLE wacrm.intent_training_phrases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  intent_id uuid NOT NULL REFERENCES wacrm.intents(id) ON DELETE CASCADE,
  phrase text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wacrm.intent_entities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  intent_id uuid NOT NULL REFERENCES wacrm.intents(id) ON DELETE CASCADE,
  name text NOT NULL,
  entity_type text NOT NULL DEFAULT 'text',
  required boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (intent_id, name)
);

