CREATE POLICY "Users can view own profile" ON wacrm.profiles FOR SELECT USING (auth.uid() = user_id);
CREATE POLICY "Users can update own profile" ON wacrm.profiles FOR UPDATE USING (auth.uid() = user_id);
CREATE POLICY "Users can insert own profile" ON wacrm.profiles FOR INSERT WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can manage own contacts" ON wacrm.contacts FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own tags" ON wacrm.tags FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage contact tags" ON wacrm.contact_tags FOR ALL
  USING (EXISTS (SELECT 1 FROM wacrm.contacts WHERE contacts.id = contact_tags.contact_id AND contacts.user_id = auth.uid()));
CREATE POLICY "Users can manage own custom fields" ON wacrm.custom_fields FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage custom values" ON wacrm.contact_custom_values FOR ALL
  USING (EXISTS (SELECT 1 FROM wacrm.contacts WHERE contacts.id = contact_custom_values.contact_id AND contacts.user_id = auth.uid()));
CREATE POLICY "Users can manage own notes" ON wacrm.contact_notes FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own conversations" ON wacrm.conversations FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can view own messages" ON wacrm.messages FOR ALL
  USING (EXISTS (SELECT 1 FROM wacrm.conversations WHERE conversations.id = messages.conversation_id AND conversations.user_id = auth.uid()));
CREATE POLICY "Service role can insert messages" ON wacrm.messages FOR INSERT WITH CHECK (true);
CREATE POLICY "Users can manage own config" ON wacrm.whatsapp_config FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own templates" ON wacrm.message_templates FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own pipelines" ON wacrm.pipelines FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage pipeline stages" ON wacrm.pipeline_stages FOR ALL
  USING (EXISTS (SELECT 1 FROM wacrm.pipelines WHERE pipelines.id = pipeline_stages.pipeline_id AND pipelines.user_id = auth.uid()));
CREATE POLICY "Users can manage own deals" ON wacrm.deals FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage own broadcasts" ON wacrm.broadcasts FOR ALL USING (auth.uid() = user_id);
CREATE POLICY "Users can manage broadcast recipients" ON wacrm.broadcast_recipients FOR ALL
  USING (EXISTS (SELECT 1 FROM wacrm.broadcasts WHERE broadcasts.id = broadcast_recipients.broadcast_id AND broadcasts.user_id = auth.uid()));
CREATE POLICY "Users can manage own automations" ON wacrm.automations FOR ALL
  USING (auth.uid() = user_id);
CREATE POLICY "Users can manage steps of own automations" ON wacrm.automation_steps FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM wacrm.automations a
      WHERE a.id = automation_steps.automation_id
        AND a.user_id = auth.uid()
    )
  );
CREATE POLICY "Users can view own automation logs" ON wacrm.automation_logs FOR ALL
  USING (auth.uid() = user_id);
CREATE POLICY "Users see reactions on their conversations" ON wacrm.message_reactions FOR SELECT
  USING (EXISTS (
    SELECT 1 FROM wacrm.conversations c
    WHERE c.id = message_reactions.conversation_id
      AND c.user_id = auth.uid()
  ));
CREATE POLICY "Users insert reactions on their conversations" ON wacrm.message_reactions FOR INSERT
  WITH CHECK (EXISTS (
    SELECT 1 FROM wacrm.conversations c
    WHERE c.id = message_reactions.conversation_id
      AND c.user_id = auth.uid()
  ));
CREATE POLICY "Users delete their own agent reactions" ON wacrm.message_reactions FOR DELETE
  USING (
    actor_type = 'agent'
    AND actor_id = auth.uid()
    AND EXISTS (
      SELECT 1 FROM wacrm.conversations c
      WHERE c.id = message_reactions.conversation_id
        AND c.user_id = auth.uid()
    )
  );
CREATE POLICY "Users update their own agent reactions" ON wacrm.message_reactions FOR UPDATE
  USING (
    actor_type = 'agent'
    AND actor_id = auth.uid()
    AND EXISTS (
      SELECT 1 FROM wacrm.conversations c
      WHERE c.id = message_reactions.conversation_id
        AND c.user_id = auth.uid()
    )
  );
CREATE POLICY "Users can manage own flows" ON wacrm.flows FOR ALL
  USING (auth.uid() = user_id);
CREATE POLICY "Users manage nodes on their flows" ON wacrm.flow_nodes FOR ALL
  USING (EXISTS (
    SELECT 1 FROM wacrm.flows f
    WHERE f.id = flow_nodes.flow_id
      AND f.user_id = auth.uid()
  ));
CREATE POLICY "Users see own flow runs" ON wacrm.flow_runs FOR SELECT
  USING (auth.uid() = user_id);
CREATE POLICY "Users see events on their runs" ON wacrm.flow_run_events FOR SELECT
  USING (EXISTS (
    SELECT 1 FROM wacrm.flow_runs r
    WHERE r.id = flow_run_events.flow_run_id
      AND r.user_id = auth.uid()
  ));
